import{c as t,U as s,j as n,g as i,o as l,a6 as o,n as r}from"./chunks/framework.h4W4t1IS.js";const b=JSON.parse('{"title":"Git","description":"","frontmatter":{"title":"Git","status":"ready","tags":["env","all"],"authors":["Jean-François Dion"],"reviewers":[]},"headers":[],"relativePath":"env/installation-git.md","filePath":"env/installation-git.md"}'),d={name:"env/installation-git.md"},p={id:"frontmatter-title",tabindex:"-1"};function c(a,e,h,u,m,g){return s(),n("div",null,[i("h1",p,[l(o(a.$frontmatter.title)+" ",1),e[0]||(e[0]=i("a",{class:"header-anchor",href:"#frontmatter-title","aria-label":'Permalink to "{{ $frontmatter.title }}"'},"​",-1))]),e[1]||(e[1]=r(`<p>Git est un gestionnaire de version de code décentralisé permettant le suivi et gestion des versions de code.</p><h2 id="objectifs-d-apprentissage" tabindex="-1">Objectifs d&#39;apprentissage <a class="header-anchor" href="#objectifs-d-apprentissage" aria-label="Permalink to &quot;Objectifs d&#39;apprentissage&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Après cette section, tu seras capable de...</p><ul><li>Configurer Git pour l&#39;utilisation en ligne de commande</li><li>Créer un dépôt de code local</li><li>Exécuter un premier <code>commit</code></li></ul></div><h2 id="telechargement" tabindex="-1">Téléchargement <a class="header-anchor" href="#telechargement" aria-label="Permalink to &quot;Téléchargement&quot;">​</a></h2><ol><li>Aller sur <a href="https://git-scm.com/install/" target="_blank" rel="noreferrer">git-scm.com</a></li><li>Choisir le système d&#39;exploitation et l&#39;architecture (<code>Windows/x64</code>)</li><li>Sélectionner <strong>Standalone installer</strong></li><li>Télécharger et exécuter l&#39;installateur</li></ol><div class="info custom-block"><p class="custom-block-title">Version</p><p>Procède au téléchargement de la version 2.*.* de Git - la version la plus récente</p></div><div class="warning custom-block"><p class="custom-block-title">Installation</p><p>Effectue l’installation normalement. Il se pourrait que l’installateur te demande la permission pour s’exécuter avec les privilèges d’administrateur. Si c’est le cas, clique sur le bouton pour accepter la demande.</p></div><h2 id="verification-de-l-installation" tabindex="-1">Vérification de l&#39;installation <a class="header-anchor" href="#verification-de-l-installation" aria-label="Permalink to &quot;Vérification de l&#39;installation&quot;">​</a></h2><p>Une fois l’installation terminée, démarre une nouvelle fenêtre de Powershell / Windows Terminal / git bash et tape la commande suivante :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>Résultat attendu (les numéros mineurs peuvent varier) :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git version 2.*.*.windows.2</span></span></code></pre></div><h2 id="utilisation-de-git" tabindex="-1">Utilisation de Git <a class="header-anchor" href="#utilisation-de-git" aria-label="Permalink to &quot;Utilisation de Git&quot;">​</a></h2><p>Git est un gestionnaire de source <strong>décentralisé</strong>, il peut être utilisé SANS dépendance externe. Un dépôt créé localement permet de faire le suivi des modifications, mais ne peut pas être partagé.</p><h3 id="initialisation-d-un-depot" tabindex="-1">Initialisation d&#39;un dépôt <a class="header-anchor" href="#initialisation-d-un-depot" aria-label="Permalink to &quot;Initialisation d&#39;un dépôt&quot;">​</a></h3><p>Pour initialiser un dépôt il suffit d&#39;exécuter la commande:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span></code></pre></div><h3 id="sauvegarde-de-code" tabindex="-1">Sauvegarde de code <a class="header-anchor" href="#sauvegarde-de-code" aria-label="Permalink to &quot;Sauvegarde de code&quot;">​</a></h3><p>Après avoir fait une modification, pour faire le suivi des changements il faut, ajouter les fichiers modifiés à l&#39;index des fichiers suivi par git.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><p>Le point (<code>.</code>) permet d&#39;ajouter TOUS les fichiers modifiés à partir du point courant dans l&#39;arborescence.</p><p>Tu peux aussi utiliser le chemin vers un fichier directement si tu ne veux pas ajouter tous les fichiers.</p><p>Tu peux ensuite commettre les changements dans le dépôt à l&#39;aide de la commande <code>commit</code></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Description des modifications apportées&quot;</span></span></code></pre></div><p>L&#39;argument <code>-m &quot;mon message&quot;</code> permet d&#39;inscrire la description des modifications dans la même commande. Si cet argument n&#39;est pas fourni, git ouvrira un éditeur texte pour te permettre de saisir le message de modification.</p><div class="info custom-block"><p class="custom-block-title">Premier commit</p><p>Lors du premier commit, tu dois fournir des renseignements pour permettre l&#39;identification de l&#39;auteur</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Your Name&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.email</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;your.email@example.com&quot;</span></span></code></pre></div><p>Le modificateur <code>--global</code> définit la configuration pour l&#39;ensemble des projets git sur ton ordinateur. Sans le modificateur, les réglages s&#39;appliqueront uniquement pour le dépôt courant.</p></div>`,26))])}const v=t(d,[["render",c]]);export{b as __pageData,v as default};
